from robot.running import EXECUTION_CONTEXTS
from robot.libraries.BuiltIn import BuiltIn


class RobotModulesLoader(object):
    @staticmethod
    def load(lib_module):
        if EXECUTION_CONTEXTS.current:
            BuiltIn().import_library(lib_module)

    @staticmethod
    def load_variables(variable_file_path):
        if EXECUTION_CONTEXTS.current:
            BuiltIn().import_variables(variable_file_path)
